#include "game/game.hpp"
#include "game/youth.hpp"
#include "game/checkpoint.hpp"
#include <cstdio>
#include <stdexcept>
using namespace em;
void require(bool v,const char* s){if(!v)throw std::runtime_error(s);}
int main(int argc,char** argv){try{
    if(argc!=3)throw std::runtime_error("youth_actions_tests DATA NATIVE");
    const std::filesystem::path data=argv[1],native=argv[2];
    const auto exe=read_file(data/"EM.EXE");
    const auto t=load_finance_tables(exe);
    // Independent literals transcribed from5396:087B, not generated by this implementation.
    struct Vector{int32_t before;int kind,x;int32_t after;};
    const Vector vectors[]{
        {0,0,120,0},{0,0,191,1500},{0,1,319,3000},{0,2,200,6000},
        {1500,0,0,0},{6000,2,120,0},{30000,0,191,30000},{60000,1,319,60000},
        {120000,2,319,120000},{0,0,121,0},{0,0,123,0},{0,0,124,1500},
        {0,0,127,3000},{0,0,131,4500},{0,0,155,15000},{0,1,155,30000},
        {0,2,155,60000},{0,0,189,28500},{0,2,190,120000},
        {123,0,120,-1377},{29997,0,191,31497},{1,0,120,1},{1,0,191,1500}};
    for(const auto& v:vectors)require(youth_funding_target(v.before,t,v.kind,v.x)==v.after,"native signed32/quantization vector");
    for(int y=0;y<240;++y){int expected=-1;for(int row=0;row<3;++row)if(y>=168+24*row&&y<=177+24*row)expected=row;
        require(youth_funding_row(y)==expected,"all240 Y positions preserve strict native hit bands");}
    Game game(exe,read_file(native/"youth-entry.hok"),2618836624u);
    const auto original=decode_game_checkpoint(game.checkpoint_bytes());
    const long expenses=monthly_expenses(t,game.budget(),true,false);
    const auto matches=[&](const char* name){require(decode_hok(game.save_bytes()).state==decode_hok(read_file(native/(std::string("youth-")+name+".hok"))).state,"all47761 native youth state bytes");};
    require(!game.adjust_youth_funding(-1,200)&&!game.adjust_youth_funding(3,200),"invalid kinds rejected");
    require(!game.adjust_youth_funding(0,120),"zero decrement is neutral");matches("entry");
    require(game.adjust_youth_funding(0,200),"native first increase");matches("step");
    require(game.adjust_youth_funding(1,155)&&game.adjust_youth_funding(2,190),"native midpoint and maximum");matches("mixed");
    require(game.adjust_youth_funding(0,190)&&game.adjust_youth_funding(1,190),"native all maximums");matches("max");
    require(game.budget().open_a07e==210000&&monthly_expenses(t,game.budget(),true,false)-expenses==210000,"all three monthly costs immediately enter the finance cache");
    require(!game.adjust_youth_funding(2,319),"maximum step is neutral");
    require(game.adjust_youth_funding(1,121)&&game.adjust_youth_funding(2,110),"native zero selection and decrement");matches("reduced");
    const auto changed=decode_game_checkpoint(game.checkpoint_bytes());
    require(changed.borland_random==original.borland_random&&changed.game_random==original.game_random&&changed.stadium_refusals==original.stadium_refusals,"funding changes neither RNG nor stadium scratch");
    Game restored(exe,game.checkpoint_bytes());
    require(restored.checkpoint_bytes()==game.checkpoint_bytes()&&restored.budget().open_a07e==144000,"OEM restores individual grants and expense cache");
    Game imported(exe,game.save_bytes());
    require(imported.save_bytes()==game.save_bytes()&&imported.budget().open_a07e==144000,"HOK restores exact grants and monthly cache");
    std::puts("Native youth actions passed");return 0;
}catch(const std::exception& e){std::fprintf(stderr,"Youth actions: %s\n",e.what());return 1;}}
